INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ich hier alles auf einmal erledigen?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlicher Workflow"}, {"text": "Ja", "correct": false, "because": "Schrittweise Bearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Visualisieren", "correct": true, "because": "Arbeit sichtbar machen"}, {"text": "Priorisieren", "correct": false, "because": "Folgt Visualisierung"}, {"text": "Analysieren", "correct": false, "because": "Später im Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen sind hier entscheidend?', 5, '[{"text": "Visualisieren", "correct": true, "because": "Übersicht schaffen"}, {"text": "Kontinuierlich bearbeiten", "correct": true, "because": "Fluss aufrechterhalten"}, {"text": "Einmalige Planung", "correct": false, "because": "Flexibel angepasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeit wird sichtbar gemacht. b) Anpassung ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anpassung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesem Ansatz?', 4, '[{"text": "Visualisierung", "correct": false, "because": "Kernprinzip"}, {"text": "Priorisierung", "correct": false, "because": "Wichtigkeit festlegen"}, {"text": "Feste Deadlines", "correct": true, "because": "Kontinuierlicher Fluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal analysiere?', 2, '[{"text": "Nein", "correct": true, "because": "Analyse fortlaufend"}, {"text": "Ja", "correct": false, "because": "Kontinuierlicher Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Aufgaben sichtbar zu machen?', 3, '[{"text": "Visualisieren", "correct": true, "because": "Board nutzen"}, {"text": "Kontinuierlich bearbeiten", "correct": false, "because": "Arbeit erledigen"}, {"text": "Anpassen", "correct": false, "because": "Später im Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern einen flexiblen Workflow?', 5, '[{"text": "Priorisieren", "correct": true, "because": "Wichtiges zuerst"}, {"text": "Anpassen", "correct": true, "because": "Prozess optimieren"}, {"text": "Einmalige Bearbeitung", "correct": false, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Visualisierung ist der Start. b) Priorisierung ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Priorisierung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Visualisierung", "correct": false, "because": "Grundlage des Prozesses"}, {"text": "Analyse", "correct": false, "because": "Verbesserung fördern"}, {"text": "Strikte Zeitpläne", "correct": true, "because": "Flexibler Fluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Bearbeite ich hier alles gleichzeitig?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich priorisiert"}, {"text": "Ja", "correct": false, "because": "Fluss gesteuert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sichern einen guten Ablauf?', 4, '[{"text": "Kontinuierlich bearbeiten", "correct": true, "because": "Fluss aufrechterhalten"}, {"text": "Analysieren", "correct": true, "because": "Schwachstellen finden"}, {"text": "Feste Zyklen", "correct": false, "because": "Flexibel gestaltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier nichts sichtbar ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Visualisierung zentral"}, {"text": "Ja", "correct": false, "because": "Board zeigt Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei neuen Aufgaben?', 3, '[{"text": "Priorisieren", "correct": true, "because": "Wichtigkeit festlegen"}, {"text": "Sofort bearbeiten", "correct": false, "because": "Fluss steuern"}, {"text": "Ignorieren", "correct": false, "because": "Visualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Analyse ist fortlaufend. b) Visualisierung ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Visualisierung kontinuierlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung möglich"}, {"text": "Transparenz", "correct": true, "because": "Visualisierung zeigt Stand"}, {"text": "Feste Deadlines", "correct": false, "because": "Kontinuierlicher Fluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Visualisierung", "correct": false, "because": "Kernprinzip"}, {"text": "Anpassung", "correct": false, "because": "Prozess verbessern"}, {"text": "Einmalige Planung", "correct": true, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Anpassung hier optional?', 3, '[{"text": "Nein", "correct": true, "because": "Verbesserung zentral"}, {"text": "Ja", "correct": false, "because": "Fortlaufend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier alles unsichtbar lasse?', 2, '[{"text": "Nein", "correct": true, "because": "Visualisierung essenziell"}, {"text": "Ja", "correct": false, "because": "Sichtbarkeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Visualisierung?', 4, '[{"text": "Priorisieren", "correct": true, "because": "Reihenfolge festlegen"}, {"text": "Analysieren", "correct": false, "because": "Später im Prozess"}, {"text": "Ignorieren", "correct": false, "because": "Bearbeitung nötig"}]');
